import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-biochemistry-carbohydrate-metabolism-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`What are the net products of glycolysis (per glucose)?`]: {
    question: r`A cell culture converts 5 molecules of glucose to pyruvate by glycolysis alone. What is the net yield?`,
    options: [r`10 pyruvate, 10 ATP and 5 NADH`, r`5 pyruvate, 10 ATP and 10 NADH`, r`10 pyruvate, 20 ATP and 10 NADH`, r`10 pyruvate, 10 ATP and 10 NADH`],
    correctAnswer: 3,
    explanation: r`Each glucose gives 2 pyruvate, a net 2 ATP and 2 NADH, so 5 glucose give 10 of each. The 20 ATP answer counts the 4 ATP made per glucose and forgets the 2 invested. The other two answers forget that each glucose is split into two trioses, each giving one pyruvate and one NADH.`,
  },
  [r`What happens to pyruvate under anaerobic conditions (fermentation)?`]: {
    question: r`A muscle extract with no oxygen converts glucose to lactate. Compared with stopping at pyruvate, what does the lactate dehydrogenase step change in the tally per glucose?`,
    options: [r`2 extra ATP; 2 NADH are reoxidized to NAD⁺`, r`No extra ATP; 2 NADH are reoxidized to NAD⁺`, r`2 extra ATP; 2 CO₂ are released from pyruvate`, r`No extra ATP; 2 NAD⁺ are reduced to NADH`],
    correctAnswer: 1,
    explanation: r`Reducing pyruvate to lactate makes no ATP; its only job is to turn NADH back into NAD⁺ so glyceraldehyde 3-phosphate dehydrogenase can keep running. Answers that add 2 ATP treat fermentation as an energy-yielding step. Reducing NAD⁺ to NADH is the reverse direction, and CO₂ release belongs to yeast ethanol fermentation, not lactate formation.`,
  },
  [r`What is gluconeogenesis and which tissues perform it?`]: {
    question: r`A patient with liver failure has fasted for two days, yet some newly synthesized glucose still enters the blood. The most likely source is:`,
    options: [r`Kidney cortex, making glucose from lactate and amino acids`, r`Brain tissue, making glucose from ketone body carbon`, r`Skeletal muscle, making glucose from its stored glycogen`, r`Adipose tissue, making glucose from fatty acid carbon`],
    correctAnswer: 0,
    explanation: r`Gluconeogenesis builds glucose from non-carbohydrate precursors and takes place mainly in liver, with the kidney as the second site. Muscle cannot release glucose and glycogen breakdown is not new synthesis. Adipose and brain do not carry out gluconeogenesis, and fatty acid and ketone carbon cannot give net glucose.`,
  },
  [r`What is the total ATP yield from complete aerobic oxidation of one glucose?`]: {
    question: r`A cell needs 60 ATP. By fermentation alone it must use 30 glucose. If it instead oxidizes glucose completely with oxygen (about 30 ATP per glucose), roughly how many glucose does it need?`,
    options: [r`About 15 glucose`, r`About 2 glucose`, r`About 6 glucose`, r`About 30 glucose`],
    correctAnswer: 1,
    explanation: r`Complete aerobic oxidation gives about 30 to 32 ATP per glucose, so 60 ATP needs about 2 glucose. Six glucose assumes only 10 ATP per glucose and 15 assumes only 4, both far below the real yield. Thirty glucose is the fermentation figure of 2 ATP per glucose.`,
  },
  [r`Contrast glycogenesis and glycogenolysis and their hormonal control.`]: {
    question: r`A runner gets a surge of epinephrine at the start of a race. In the liver, which pair of enzyme states results?`,
    options: [r`Glycogen phosphorylase off, glycogen synthase on`, r`Glycogen phosphorylase off, glycogen synthase off`, r`Glycogen phosphorylase on, glycogen synthase off`, r`Glycogen phosphorylase on, glycogen synthase on`],
    correctAnswer: 2,
    explanation: r`Epinephrine, like glucagon, drives glycogenolysis, so glycogen phosphorylase is switched on while glycogen synthase is switched off. The reverse pair is the insulin pattern of the fed state. Both on would be a futile cycle and both off would mobilize nothing, so the two enzymes are always set oppositely.`,
  },
  [r`What does pyruvate dehydrogenase do, and what does it produce?`]: {
    question: r`Three glucose molecules are converted to pyruvate, and all of that pyruvate passes through pyruvate dehydrogenase. What does the pyruvate dehydrogenase step alone produce?`,
    options: [r`6 CO₂ and 6 NADH`, r`6 CO₂ and 12 NADH`, r`12 CO₂ and 6 NADH`, r`3 CO₂ and 3 NADH`],
    correctAnswer: 0,
    explanation: r`Three glucose give 6 pyruvate, and each pyruvate releases 1 CO₂ and makes 1 NADH as it becomes acetyl-CoA, so the totals are 6 and 6. Three of each forgets that one glucose gives two pyruvate. The answers with 12 double one product, although the complex makes exactly one of each per pyruvate.`,
  },
  [r`What is the purpose of the pentose phosphate pathway (HMP shunt)?`]: {
    question: r`Lymphocytes that are dividing rapidly and are exposed to peroxide increase flux through a cytosolic pathway that makes no ATP. Blocking this pathway would most directly impair:`,
    options: [r`nucleotide synthesis and glutathione regeneration`, r`nucleotide synthesis and lactate production`, r`oxidative phosphorylation and lactate production`, r`fatty acid oxidation and glutathione regeneration`],
    correctAnswer: 0,
    explanation: r`The pathway is the pentose phosphate pathway, which supplies ribose 5-phosphate for nucleotides and NADPH to keep glutathione reduced. Lactate production depends on glycolysis and NADH, not on this pathway. Fatty acid oxidation and oxidative phosphorylation are mitochondrial processes that do not use its products.`,
  },
  [r`How do insulin and glucagon oppositely regulate blood glucose?`]: {
    question: r`A tumor of pancreatic alpha cells secretes its hormone continuously. Which finding is expected?`,
    options: [r`Low blood glucose from raised GLUT4 uptake and hepatic glycogen synthesis`, r`Low blood glucose from reduced hepatic glycogenolysis and gluconeogenesis`, r`High blood glucose from raised muscle glycogenolysis and fat synthesis`, r`High blood glucose from raised hepatic glycogenolysis and gluconeogenesis`],
    correctAnswer: 3,
    explanation: r`Alpha cells make glucagon, which raises blood glucose by stimulating liver glycogen breakdown and gluconeogenesis. The low-glucose answers describe insulin from beta cells or the opposite of glucagon's action. Glucagon does not act on muscle glycogen and does not promote fat synthesis, which is an insulin effect.`,
  },
  [r`How many ATP per NADH and FADH₂ in oxidative phosphorylation?`]: {
    question: r`Oxidation of a fuel delivers 4 NADH and 2 FADH₂ to the electron transport chain. Using the modern values, about how much ATP does oxidative phosphorylation make from them?`,
    options: [r`About 11 ATP`, r`About 13 ATP`, r`About 16 ATP`, r`About 15 ATP`],
    correctAnswer: 1,
    explanation: r`NADH gives about 2.5 ATP and FADH₂ about 1.5, so 4 × 2.5 + 2 × 1.5 = 13. Fifteen treats FADH₂ as if it were worth 2.5, ignoring that it enters at Complex II and pumps fewer protons. Eleven swaps the two values, and 16 uses the older figures of 3 and 2.`,
  },
  [r`Where does the electron transport chain occur and what is the final electron acceptor?`]: {
    question: r`A toxin makes the inner mitochondrial membrane freely permeable to protons, while electrons still flow to O₂. What happens to ATP synthesis?`,
    options: [r`It falls, because the gradient that drives ATP synthase collapses`, r`It rises, because the complexes can pump protons at a faster rate`, r`It is unchanged, because ATP synthase is driven directly by NADH`, r`It falls, because O₂ can no longer accept electrons at Complex IV`],
    correctAnswer: 0,
    explanation: r`ATP synthase is powered by the proton gradient that Complexes I to IV build across the inner mitochondrial membrane, so a leaky membrane stops ATP synthesis even though electrons still reach O₂. Faster pumping cannot help if the protons leak straight back. The question states O₂ is still reduced, and ATP synthase never uses NADH directly.`,
  },
  [r`Which three enzymes regulate the TCA cycle, and what turns them up or down?`]: {
    question: r`A drug mimics NADH at the rate-limiting enzyme of the TCA cycle and holds it in its inhibited state. Which conversion is most directly slowed?`,
    options: [r`Succinyl-CoA to free succinate`, r`Succinate to fumarate at Complex II`, r`Isocitrate to α-ketoglutarate`, r`Citrate to isocitrate by aconitase`],
    correctAnswer: 2,
    explanation: r`The rate-limiting enzyme is isocitrate dehydrogenase, which converts isocitrate to α-ketoglutarate and is inhibited by NADH and ATP. Succinate to fumarate is succinate dehydrogenase, citrate to isocitrate is aconitase, and succinyl-CoA to succinate is the GTP-forming step. None of those three is a regulated control point of the cycle.`,
  },
  [r`Why do the malate-aspartate and glycerol-3-phosphate shuttles give different ATP yields?`]: {
    question: r`Glycolysis makes 2 cytosolic NADH per glucose. Compared with a muscle cell using the glycerol 3-phosphate shuttle, a heart cell using the malate-aspartate shuttle gets how much ATP per glucose from them?`,
    options: [r`About 5 ATP more`, r`About 1 ATP more`, r`About 2 ATP more`, r`About 2 ATP fewer`],
    correctAnswer: 2,
    explanation: r`The malate-aspartate shuttle regenerates NADH in the matrix (about 2.5 ATP each), while the glycerol 3-phosphate shuttle gives FADH₂ (about 1.5 ATP each). The gain is 1 ATP per NADH, so 2 per glucose. One ATP forgets there are two NADH, 2 fewer reverses the shuttles, and 5 counts the full value of the NADH instead of the difference.`,
  },
  [r`What are the products of ONE turn of the TCA (Krebs) cycle?`]: {
    question: r`A mitochondrion oxidizes 4 acetyl-CoA through the TCA cycle. What are the total products?`,
    options: [r`12 NADH, 8 FADH₂, 4 GTP and 8 CO₂`, r`12 NADH, 4 FADH₂, 4 GTP and 4 CO₂`, r`8 NADH, 4 FADH₂, 4 GTP and 8 CO₂`, r`12 NADH, 4 FADH₂, 4 GTP and 8 CO₂`],
    correctAnswer: 3,
    explanation: r`One turn gives 3 NADH, 1 FADH₂, 1 GTP and 2 CO₂, so four turns give 12, 4, 4 and 8. The answer with 4 CO₂ counts only one decarboxylation per turn, but both dehydrogenase steps release CO₂. The answers with 8 NADH or 8 FADH₂ use 2 per turn where the cycle makes 3 NADH and only 1 FADH₂.`,
  },
  [r`What is the rate-limiting (committed) enzyme of glycolysis and how is it regulated?`]: {
    question: r`A heart cell switches to burning fatty acids, and citrate made in its mitochondria spills into the cytosol. What is the effect on glycolysis?`,
    options: [r`Citrate activates PFK-1, so glycolysis speeds up`, r`Citrate activates pyruvate kinase, so glycolysis speeds up`, r`Citrate inhibits hexokinase, so glycolysis slows`, r`Citrate inhibits PFK-1, so glycolysis slows`],
    correctAnswer: 3,
    explanation: r`Citrate signals that the cell already has plenty of fuel, and like ATP it inhibits phosphofructokinase-1, the committed step of glycolysis. Calling citrate an activator reverses the logic of an energy-abundance signal. Hexokinase is inhibited by glucose 6-phosphate, not citrate, and pyruvate kinase is activated by fructose 1,6-bisphosphate.`,
  },
  [r`The rate-limiting enzyme of glycolysis is {{c1::phosphofructokinase-1 (PFK-1)}}.`]: {
    question: r`In a liver cell, glucose 6-phosphate can still go to glycogen or the pentose phosphate pathway, and fructose 6-phosphate can convert back to it. Which reaction first commits the carbon to glycolysis?`,
    options: [r`Fructose 6-phosphate to fructose 1,6-bisphosphate`, r`Phosphoenolpyruvate to pyruvate by pyruvate kinase`, r`Glucose to glucose 6-phosphate by hexokinase`, r`Glucose 6-phosphate to fructose 6-phosphate`],
    correctAnswer: 0,
    explanation: r`Phosphofructokinase-1 makes fructose 1,6-bisphosphate, which has no fate other than glycolysis, so this is the committed, rate-limiting step. Phosphorylating glucose does not commit it, because glucose 6-phosphate feeds several pathways, and the isomerase step is freely reversible. Pyruvate kinase is irreversible but comes long after the commitment.`,
  },
  [r`How does the glucose-alanine cycle differ functionally from the Cori cycle?`]: {
    question: r`Fasting muscle that is breaking down protein exports alanine rather than lactate. What does the alanine route let the liver do that the lactate route does not?`,
    options: [r`Make new glucose without spending ATP`, r`Release ketone bodies for muscle to burn`, r`Regenerate NAD⁺ for muscle glycolysis`, r`Dispose of muscle amino nitrogen as urea`],
    correctAnswer: 3,
    explanation: r`Alanine carries both the pyruvate carbon and an amino group to the liver, where the nitrogen enters the urea cycle; lactate in the Cori cycle carries carbon only. NAD⁺ regeneration is what lactate formation does in muscle. Gluconeogenesis from either carrier costs ATP, and ketone bodies come from fatty acids, not from this cycle.`,
  },
  [r`What two activities does the glycogen debranching enzyme perform, and which product is free glucose?`]: {
    question: r`A mutant debranching enzyme keeps its transferase activity but has lost its α-1,6-glucosidase activity. After phosphorylase and the transferase act near a branch, what is left at the branch point?`,
    options: [r`A free glucose released by hydrolysis`, r`A single glucose held by an α-1,6 bond`, r`A glucose 1-phosphate released by Pᵢ`, r`Four glucoses held by α-1,4 bonds`],
    correctAnswer: 1,
    explanation: r`The transferase moves three of the four remaining residues to another chain end, leaving one glucose attached by its α-1,6 bond; only the glucosidase can remove it. A four-residue stub is what remains before the transferase acts. Free glucose is the product of the missing glucosidase, and phosphorylase cannot cleave an α-1,6 bond to give glucose 1-phosphate.`,
  },
  [r`Phosphorylase kinase is fully active when phosphorylated by {{c1::PKA}} AND bound by {{c2::$Ca^{2+}$-calmodulin}} (its delta subunit).`]: {
    question: r`In which condition is phosphorylase kinase in skeletal muscle most fully active?`,
    options: [r`Epinephrine present and the muscle at rest`, r`Insulin present and the muscle contracting`, r`Insulin present and the muscle at rest`, r`Epinephrine present and the muscle contracting`],
    correctAnswer: 3,
    explanation: r`Full activity needs both phosphorylation by PKA, which epinephrine triggers, and Ca²⁺ bound to the enzyme's calmodulin subunit, which contraction supplies. Epinephrine at rest or contraction without epinephrine gives only partial activation. Insulin opposes PKA signaling, so it does not switch the kinase on.`,
  },
  [r`Glycogen synthase cannot start a chain de novo. What primes glycogen synthesis?`]: {
    question: r`Cells are engineered so that glycogenin's key tyrosine is replaced by phenylalanine. Glycogen synthase and UDP-glucose are normal. What is the result?`,
    options: [r`No new granules form, since no primer can be built`, r`No UDP-glucose forms, since glycogenin produces it`, r`New granules form, since synthase starts its own chains`, r`Granules lack branches, since glycogenin adds them`],
    correctAnswer: 0,
    explanation: r`Glycogenin attaches the first glucose to its own tyrosine and extends it to a short primer; glycogen synthase can only lengthen an existing chain. Without the tyrosine no primer exists, so no granule starts. UDP-glucose is made by UDP-glucose pyrophosphorylase, and branches are added by branching enzyme, not by glycogenin.`,
  },
  [r`A cell needs ribose 5-phosphate but no NADPH (rapid division, ample reducing power). How does the PPP accommodate this?`]: {
    question: r`A dividing cell has its glucose 6-phosphate dehydrogenase fully inhibited, yet it still makes ribose 5-phosphate for DNA synthesis. Where does the carbon come from?`,
    options: [r`Pyruvate and oxaloacetate, via pyruvate carboxylase and PEP carboxykinase`, r`Fructose 6-phosphate and glyceraldehyde 3-phosphate, via transketolase and transaldolase`, r`Glucose 6-phosphate and 6-phosphogluconate, via the oxidative branch dehydrogenases`, r`Acetyl-CoA and glycerol 3-phosphate, via citrate synthase and transaldolase`],
    correctAnswer: 1,
    explanation: r`The nonoxidative branch is reversible, so transketolase and transaldolase can build ribose 5-phosphate from the glycolytic intermediates fructose 6-phosphate and glyceraldehyde 3-phosphate without making NADPH. The oxidative branch is blocked at its first enzyme here. The gluconeogenic and TCA enzymes named in the other answers do not make pentoses.`,
  },
  [r`How does liver glycogen phosphorylase a itself act as a blood-glucose sensor?`]: {
    question: r`Hepatocytes express a glycogen phosphorylase a that cannot bind glucose at its allosteric site. Blood glucose rises with no change in hormones. Compared with normal cells:`,
    options: [r`Phosphorylase is inactivated and synthase activation is delayed`, r`Phosphorylase is inactivated and synthase is activated at once`, r`Phosphorylase stays active and synthase is activated at once`, r`Phosphorylase stays active and synthase activation is delayed`],
    correctAnswer: 3,
    explanation: r`Glucose binding normally changes phosphorylase a so that PP1 can dephosphorylate it; the freed PP1 then activates glycogen synthase. Without glucose binding, phosphorylase stays active and PP1 is not freed, so synthase stays off. The other answers either inactivate an enzyme that can no longer sense glucose or activate synthase without PP1 being freed.`,
  },
  [r`Why does Pompe disease damage the heart while leaving blood glucose normal?`]: {
    question: r`An infant with Pompe disease is fasted overnight. What is the expected blood glucose, and why?`,
    options: [r`Normal, because cytosolic glycogen breakdown still works`, r`High, because muscle can no longer take up blood glucose`, r`Low, because liver glycogen cannot be broken down at all`, r`Low, because gluconeogenesis has lost its final enzyme`],
    correctAnswer: 0,
    explanation: r`Pompe disease is a deficiency of the lysosomal acid α-glucosidase, so glycogen builds up inside lysosomes and damages heart and muscle. Cytosolic glycogen phosphorylase and gluconeogenesis are untouched, so fasting glucose is normal. Failed liver glycogenolysis or a lost final enzyme describes other storage diseases, and glucose uptake is not affected.`,
  },
  [r`How does Cori disease (debrancher deficiency) differ biochemically from Von Gierke disease?`]: {
    question: r`Two fasting children have large livers and low blood glucose. Child 1 has high blood lactate. Child 2 has normal lactate, milder hypoglycemia, and glycogen with very short outer branches. Child 2 most likely lacks:`,
    options: [r`Debranching enzyme, with gluconeogenesis intact`, r`Branching enzyme, with gluconeogenesis blocked`, r`Muscle phosphorylase, with gluconeogenesis intact`, r`Glucose 6-phosphatase, with gluconeogenesis blocked`],
    correctAnswer: 0,
    explanation: r`Short outer branches (limit dextrins) with normal lactate point to Cori disease, a debranching enzyme deficiency in which gluconeogenesis still releases glucose. Glucose 6-phosphatase deficiency is Child 1: it blocks both pathways and adds lactic acidosis. Branching enzyme deficiency gives long unbranched chains, and muscle phosphorylase deficiency spares the liver.`,
  },
  [r`What does the Rapoport-Luebering (2,3-BPG) shunt in red blood cells cost energetically, and why is it worth it?`]: {
    question: r`At high altitude, red blood cells send more of their 1,3-bisphosphoglycerate through the 2,3-BPG shunt. What are the two consequences?`,
    options: [r`Net ATP per glucose rises; hemoglobin O₂ affinity rises`, r`Net ATP per glucose falls; hemoglobin O₂ affinity rises`, r`Net ATP per glucose rises; hemoglobin O₂ affinity falls`, r`Net ATP per glucose falls; hemoglobin O₂ affinity falls`],
    correctAnswer: 3,
    explanation: r`The shunt bypasses phosphoglycerate kinase, so the cell gives up one ATP for each triose that takes it. The 2,3-BPG made stabilizes the T state of deoxyhemoglobin, lowering O₂ affinity and helping unloading in tissues. Answers with rising ATP ignore the skipped kinase step, and rising affinity reverses the effect of 2,3-BPG.`,
  },
  [r`Hepatic {{c1::glucokinase}} has a {{c2::high}} $K_m$ (~10 mM) and, unlike hexokinase, is NOT inhibited by {{c3::glucose 6-phosphate}}.`]: {
    question: r`After a meal, portal blood glucose rises from 5 mM to 10 mM. How do the rates of hexokinase (Km about 0.1 mM) and hepatic glucokinase (Km about 10 mM) respond?`,
    options: [r`Hexokinase rate rises markedly; glucokinase stays near Vmax`, r`Both enzymes roughly double their rates across this range`, r`Both enzymes stay near Vmax across this glucose range`, r`Hexokinase stays near Vmax; glucokinase rate rises markedly`],
    correctAnswer: 3,
    explanation: r`Hexokinase is already saturated at 5 mM because its Km is far lower, so it cannot respond. Glucokinase has a high Km, so its rate climbs from about one third to one half of Vmax, tracking blood glucose. Swapping the enzymes confuses the two Km values, and neither 'both saturated' nor 'both double' fits enzymes with Km values 100-fold apart.`,
  },
  [r`{{c1::GLUT2}} (liver, beta cells) is high-$K_m$ and insulin-independent; {{c2::GLUT4}} (muscle, adipose) is insulin-recruited.`]: {
    question: r`During an overnight fast insulin is low. Which tissue's glucose uptake falls most because its glucose transporters are withdrawn from the cell surface?`,
    options: [r`Circulating red cells, which use GLUT1`, r`Liver parenchymal cells, which use GLUT2`, r`Resting skeletal muscle, which uses GLUT4`, r`Neurons of the brain, which use GLUT3`],
    correctAnswer: 2,
    explanation: r`GLUT4 sits in intracellular vesicles and reaches the surface of muscle and fat cells only when insulin (or contraction) signals, so resting muscle takes up little glucose in a fast. GLUT2 in liver is insulin-independent and always in the membrane. GLUT3 and GLUT1 are low-Km, insulin-independent transporters that keep brain and red cells supplied.`,
  },
  [r`Three irreversible glycolytic steps are bypassed by which four gluconeogenic enzymes?`]: {
    question: r`A patient's liver lacks fructose 1,6-bisphosphatase. During a fast, which source can still be released from the liver as glucose?`,
    options: [r`Glucose 1-phosphate from liver glycogen`, r`Lactate arriving from red blood cells`, r`Alanine arriving from skeletal muscle`, r`Glycerol arriving from adipose tissue`],
    correctAnswer: 0,
    explanation: r`Glycogen-derived glucose 1-phosphate becomes glucose 6-phosphate and needs only glucose 6-phosphatase, so it does not pass the missing bypass enzyme. Lactate and alanine enter as pyruvate, and glycerol enters as dihydroxyacetone phosphate; all three must pass through fructose 1,6-bisphosphate and need the bisphosphatase that bypasses PFK-1.`,
  },
  [r`Pyruvate carboxylase is located in the {{c1::mitochondrial matrix}}, uses the cofactor {{c2::biotin}}, and requires the allosteric activator {{c3::acetyl-CoA}}.`]: {
    question: r`During a fast, fatty acid oxidation raises acetyl-CoA in the liver mitochondrial matrix. What is the main fate of pyruvate there?`,
    options: [r`Carboxylated to oxaloacetate; pyruvate carboxylase is activated`, r`Oxidized to acetyl-CoA; pyruvate dehydrogenase is activated`, r`Carboxylated to oxaloacetate; pyruvate dehydrogenase is activated`, r`Oxidized to acetyl-CoA; pyruvate carboxylase is inhibited`],
    correctAnswer: 0,
    explanation: r`Acetyl-CoA is the required allosteric activator of pyruvate carboxylase, the biotin enzyme in the matrix that makes oxaloacetate for gluconeogenesis. The same acetyl-CoA inhibits pyruvate dehydrogenase, so pyruvate is not oxidized. The mixed answers pair the right product with the wrong enzyme or reverse acetyl-CoA's effect on the carboxylase.`,
  },
  [r`Where in the cell does glucose 6-phosphatase act, and which tissues have it?`]: {
    question: r`A patient has a normal glucose 6-phosphatase catalytic subunit but a defective transporter that carries glucose 6-phosphate across the endoplasmic reticulum membrane. What is expected during a fast?`,
    options: [r`Normal glucose, as the same enzyme in muscle covers for the liver`, r`Hypoglycemia, as the substrate cannot enter the mitochondrial matrix`, r`Hypoglycemia, as the substrate cannot reach the enzyme in the ER lumen`, r`Normal glucose, as the enzyme hydrolyzes its substrate in the cytosol`],
    correctAnswer: 2,
    explanation: r`Glucose 6-phosphatase faces the lumen of the endoplasmic reticulum, so glucose 6-phosphate must be carried in before it can be hydrolyzed; without the transporter no glucose is released. The enzyme is not cytosolic or mitochondrial. Muscle lacks glucose 6-phosphatase entirely, so it cannot compensate.`,
  },
  [r`In the Cori cycle, muscle gains 2 ATP per glucose while the liver spends 6 regenerating it. What is the physiological point of the net 4-ATP loss?`]: {
    question: r`During a sprint, the liver turns muscle lactate back into glucose at a cost of 6 ATP per glucose. Where does the liver mainly get this ATP?`,
    options: [r`Oxidation of fatty acids in its mitochondria`, r`ATP sent through the blood by the muscle`, r`Glycolysis of the glucose it has just made`, r`Fermentation of the lactate it has taken up`],
    correctAnswer: 0,
    explanation: r`The Cori cycle moves the energy cost to the well-oxygenated liver, which pays for gluconeogenesis with aerobic fatty acid oxidation while muscle gets fast anaerobic ATP. Glycolyzing the new glucose would return only 2 ATP and undo the work. Lactate is not fermented further, and ATP is not transported between tissues in blood.`,
  },
  [r`Why can PFK-1 run at high rates in a fed liver cell even when ATP levels are high?`]: {
    question: r`Liver PFK-1 is assayed at a high ATP concentration. Fructose 2,6-bisphosphate is then added. How does the plot of rate against fructose 6-phosphate concentration change?`,
    options: [r`Shifts right: more substrate gives half-maximal rate`, r`Stays put, but the maximal rate is cut in half`, r`Shifts left: less substrate gives half-maximal rate`, r`Stays put, since ATP inhibition cannot be relieved`],
    correctAnswer: 2,
    explanation: r`Fructose 2,6-bisphosphate raises PFK-1's affinity for fructose 6-phosphate, which shifts the curve left and overcomes the inhibition by ATP. A right shift is what ATP itself does. The activator does not lower the maximal rate, and ATP inhibition is allosteric and can be relieved, which is why a fed liver can run glycolysis with high ATP.`,
  },
  [r`Arsenate lets glycolysis continue but abolishes ATP gain at phosphoglycerate kinase. What is the mechanism?`]: {
    question: r`Red blood cells are incubated with arsenate, and glucose is still converted to pyruvate. Per glucose, what is the net yield?`,
    options: [r`2 ATP and 2 NADH`, r`0 ATP and 0 NADH`, r`0 ATP and 2 NADH`, r`4 ATP and 2 NADH`],
    correctAnswer: 2,
    explanation: r`Arsenate replaces phosphate at glyceraldehyde 3-phosphate dehydrogenase, and the product breaks down to 3-phosphoglycerate without passing through phosphoglycerate kinase. Only pyruvate kinase makes ATP (2), which just repays the 2 invested, so net ATP is 0 while NADH is still made. Two ATP is the normal net, and 4 ignores both the loss and the investment.`,
  },
  [r`How is glucokinase activity controlled acutely in hepatocytes, given that G6P does not inhibit it?`]: {
    question: r`After a sugary drink, fructose 1-phosphate and glucose rise in hepatocytes. What happens to glucokinase?`,
    options: [r`It is phosphorylated by PKA and switched off in the cytosol`, r`It is released by its regulatory protein into the cytosol`, r`It is bound by its regulatory protein inside the nucleus`, r`It is inhibited directly by rising glucose 6-phosphate`],
    correctAnswer: 1,
    explanation: r`Glucokinase regulatory protein holds glucokinase in the nucleus when glucose is low; glucose and fructose 1-phosphate trigger its release to the cytosol, where it works. Binding in the nucleus is promoted by fructose 6-phosphate in the fasted state. Glucose 6-phosphate inhibits hexokinase, not glucokinase, and PKA phosphorylation is not how this enzyme is controlled.`,
  },
  [r`Which glycolytic enzyme does fluoride inhibit, and what practical use follows?`]: {
    question: r`Red blood cells are treated with fluoride. Which glycolytic intermediate builds up, and why?`,
    options: [r`Glyceraldehyde 3-phosphate, because GAPDH is blocked`, r`Fructose 6-phosphate, because PFK-1 is blocked`, r`2-Phosphoglycerate, because enolase is blocked`, r`Phosphoenolpyruvate, because enolase is blocked`],
    correctAnswer: 2,
    explanation: r`Fluoride inhibits enolase, which converts 2-phosphoglycerate to phosphoenolpyruvate, so the substrate 2-phosphoglycerate accumulates. Phosphoenolpyruvate is the product and would fall. A block at glyceraldehyde 3-phosphate dehydrogenase is the action of iodoacetate, and fluoride does not act on PFK-1.`,
  },
  [r`Why is glycogen branched at all — what do the alpha-1,6 linkages accomplish?`]: {
    question: r`Equal masses of normal glycogen and of glycogen with almost no branches are each mixed with glycogen phosphorylase and phosphate. How do the initial rates of glucose 1-phosphate release compare?`,
    options: [r`Slower for the unbranched sample, which has few reducing ends`, r`Slower for the unbranched sample, which has few nonreducing ends`, r`Equal for the two samples, which contain the same mass of glucose`, r`Faster for the unbranched sample, which has no α-1,6 links to stall at`],
    correctAnswer: 1,
    explanation: r`Phosphorylase removes glucose only from nonreducing ends, and branching multiplies those ends, so highly branched glycogen is mobilized far faster. An unbranched chain offers one such end. Reducing ends are not where the enzyme works, and equal glucose mass does not mean equal numbers of chain ends.`,
  },
  [r`Why does pyruvate kinase deficiency cause hemolytic anemia, and what partially compensates for the oxygen-delivery problem?`]: {
    question: r`A patient with pyruvate kinase deficiency tolerates exercise better than the low hemoglobin level would predict. What is the best explanation?`,
    options: [r`Raised 2,3-BPG lowers the O₂ affinity of hemoglobin`, r`Raised NADPH protects hemoglobin against oxidation`, r`Lowered 2,3-BPG raises the O₂ affinity of hemoglobin`, r`Raised ATP lets red cell ion pumps work much faster`],
    correctAnswer: 0,
    explanation: r`With pyruvate kinase blocked, upstream intermediates accumulate and more 2,3-BPG forms, which shifts the oxygen dissociation curve to the right and improves unloading in tissues. Lower 2,3-BPG and higher affinity would make delivery worse. ATP falls rather than rises in this disease, and NADPH comes from a different pathway.`,
  },
  [r`What nucleotide does PEP carboxykinase use, and how is the enzyme chiefly regulated?`]: {
    question: r`A hepatocyte converts 2 oxaloacetate to 2 phosphoenolpyruvate with PEP carboxykinase. What does this step consume and release?`,
    options: [r`2 GTP consumed and 2 CO₂ released`, r`2 GTP consumed and 2 CO₂ fixed`, r`2 ATP consumed and 2 CO₂ fixed`, r`2 ATP consumed and 2 CO₂ released`],
    correctAnswer: 0,
    explanation: r`PEP carboxykinase uses one GTP per oxaloacetate and removes the carboxyl group as CO₂, and the decarboxylation helps drive the reaction. Naming ATP confuses it with pyruvate carboxylase, the preceding step. Fixing CO₂ is also what pyruvate carboxylase does; PEP carboxykinase releases that same carbon.`,
  },
  [r`Why does gluconeogenic oxaloacetate leave the mitochondrion as malate during fasting?`]: {
    question: r`A hepatocyte is making glucose from lactate rather than from alanine. Why can the oxaloacetate carbon leave the mitochondrion as aspartate instead of malate in this case?`,
    options: [r`Lactate oxidation to pyruvate already supplies cytosolic ATP`, r`Aspartate carries more reducing power out than malate does`, r`Lactate oxidation to pyruvate already supplies cytosolic NADH`, r`Oxaloacetate itself crosses the membrane when lactate is high`],
    correctAnswer: 2,
    explanation: r`The malate route exports NADH along with carbon, which the cytosol needs to run glyceraldehyde 3-phosphate dehydrogenase in reverse. Lactate dehydrogenase makes that NADH in the cytosol when lactate is the precursor, so the aspartate route, which carries no reducing power, is enough. The step makes no ATP, and oxaloacetate never crosses the inner membrane directly.`,
  },
  [r`Why does glucagon not mobilize muscle glycogen, and what hormone does instead?`]: {
    question: r`Epinephrine stimulates glycogen breakdown in a resting skeletal muscle. What happens to the glucose 6-phosphate that results?`,
    options: [r`It leaves as blood glucose, as muscle lacks glucagon receptors`, r`It enters glycolysis there, as muscle lacks glucose transporters`, r`It enters glycolysis there, as muscle lacks glucose 6-phosphatase`, r`It leaves as blood glucose, as muscle has glucose 6-phosphatase`],
    correctAnswer: 2,
    explanation: r`Muscle responds to epinephrine, not glucagon, and it has no glucose 6-phosphatase, so the glucose 6-phosphate cannot be converted to free glucose and is used inside the same cell. Answers that export glucose assume an enzyme muscle does not have. Muscle does have glucose transporters, and the lack of glucagon receptors does not create an export route.`,
  },
  [r`1,3-BPG's high-energy {{c1::acyl phosphate}} lets {{c2::phosphoglycerate kinase}} form ATP by substrate-level phosphorylation.`]: {
    question: r`Hydrolysis of the acyl phosphate of 1,3-bisphosphoglycerate has ΔG°′ of about −49 kJ/mol, and hydrolysis of ATP to ADP about −30 kJ/mol. What is ΔG°′ for phosphoglycerate kinase transferring that phosphate to ADP?`,
    options: [r`About −79 kJ/mol, so ATP formation is favorable`, r`About −19 kJ/mol, so ATP formation is favorable`, r`About +19 kJ/mol, so ATP formation is unfavorable`, r`About +79 kJ/mol, so ATP formation is unfavorable`],
    correctAnswer: 1,
    explanation: r`The transfer is acyl phosphate hydrolysis (−49) plus the reverse of ATP hydrolysis (+30), giving −19 kJ/mol, so substrate-level phosphorylation runs forward. Plus 19 reverses both signs. The answers with 79 add the two magnitudes instead of taking the difference between donor and acceptor.`,
  },
  [r`Pyruvate kinase: feedforward-activated by {{c1::F1,6BP}}, inhibited by ATP and {{c2::alanine}}; liver isozyme inactivated by {{c3::PKA phosphorylation}}.`]: {
    question: r`During a fast, glucagon leads to phosphorylation of pyruvate kinase in the liver. What is the consequence?`,
    options: [r`Liver enzyme is switched off; PEP is kept for gluconeogenesis`, r`Liver enzyme is switched off; PEP is diverted to glycolysis`, r`Liver enzyme is switched on; PEP is kept for gluconeogenesis`, r`Muscle enzyme is switched off; PEP is kept for gluconeogenesis`],
    correctAnswer: 0,
    explanation: r`PKA phosphorylation inactivates the liver isozyme of pyruvate kinase, so phosphoenolpyruvate made by gluconeogenesis is not cycled back to pyruvate. Switching the enzyme on would waste that PEP. With pyruvate kinase off PEP cannot be 'diverted to glycolysis', and the muscle isozyme is not controlled by this phosphorylation.`,
  },
  [r`Fructose 1,6-bisphosphatase is allosterically inhibited by {{c1::AMP}} and {{c2::fructose 2,6-bisphosphate}}.`]: {
    question: r`A poison makes AMP rise sharply in hepatocytes. What happens to phosphofructokinase-1 and fructose 1,6-bisphosphatase?`,
    options: [r`PFK-1 is inhibited; the bisphosphatase is activated`, r`PFK-1 is activated; the bisphosphatase is activated`, r`PFK-1 is inhibited; the bisphosphatase is inhibited`, r`PFK-1 is activated; the bisphosphatase is inhibited`],
    correctAnswer: 3,
    explanation: r`AMP signals low energy charge: it activates PFK-1 to speed glycolysis and inhibits fructose 1,6-bisphosphatase so ATP is not spent making glucose. The reversed answer describes a high-energy, fasting-hormone state. The two enzymes are always regulated in opposite directions, which prevents a futile cycle.`,
  },
  [r`Glucagon acts via {{c1::PKA}} phosphorylation of the bifunctional enzyme, activating hepatic {{c2::FBPase-2}} and lowering {{c3::fructose 2,6-bisphosphate}}.`]: {
    question: r`Liver cells express a bifunctional PFK-2/FBPase-2 whose PKA target serine is replaced by alanine. When glucagon is added, what happens?`,
    options: [r`Fructose 2,6-bisphosphate falls and PFK-1 is inhibited`, r`Fructose 2,6-bisphosphate stays high and PFK-1 is inhibited`, r`Fructose 2,6-bisphosphate stays high and PFK-1 stays active`, r`Fructose 2,6-bisphosphate falls and PFK-1 stays active`],
    correctAnswer: 2,
    explanation: r`Glucagon normally works through PKA phosphorylation of the bifunctional enzyme, which turns on its phosphatase side and lowers fructose 2,6-bisphosphate. If the enzyme cannot be phosphorylated, the activator stays high and PFK-1 stays active. A fall with PFK-1 inhibited is the normal response, and the mixed answers break the link between the activator's level and PFK-1.`,
  },
  [r`Glycogen phosphorylase cleaves by {{c1::phosphorolysis}} using $P_i$ to release {{c2::glucose 1-phosphate}}, with {{c3::pyridoxal phosphate}} as cofactor.`]: {
    question: r`In muscle, glycogen phosphorylase releases one glucose residue, which is then carried through glycolysis to pyruvate. What is the net ATP yield for that residue?`,
    options: [r`1 ATP`, r`2 ATP`, r`4 ATP`, r`3 ATP`],
    correctAnswer: 3,
    explanation: r`Phosphorolysis gives glucose 1-phosphate, which is converted to glucose 6-phosphate without ATP, so only PFK-1 uses an ATP: 4 made minus 1 invested is 3. Two ATP is the yield from free glucose, which needs hexokinase too. Four ignores the PFK-1 investment, and 1 subtracts an investment that does not exist.`,
  },
  [r`Glycogen synthase is inactivated by phosphorylation via {{c1::GSK-3 and PKA}}, and reactivated when insulin stimulates {{c2::protein phosphatase 1 (PP1)}}.`]: {
    question: r`Hepatocytes with no insulin present are treated with a drug that inhibits GSK-3. What happens to glycogen synthase?`,
    options: [r`It becomes more phosphorylated and more active`, r`It becomes more phosphorylated and less active`, r`It becomes less phosphorylated and more active`, r`It becomes less phosphorylated and less active`],
    correctAnswer: 2,
    explanation: r`GSK-3 phosphorylates glycogen synthase, and the phosphorylated form is the inactive one. Blocking GSK-3 leaves phosphatase action unopposed, so the enzyme becomes less phosphorylated and more active, copying part of insulin's effect. The other answers either reverse the effect of the drug or reverse the rule that phosphorylation switches synthase off.`,
  },
  [r`{{c1::Glucose 6-phosphate dehydrogenase}} is the committed, rate-limiting PPP step; it is inhibited by its product {{c2::NADPH}} and induced by {{c3::insulin}}.`]: {
    question: r`Rats moved from fasting to a high-carbohydrate diet for several days show a several-fold rise in the amount of liver glucose 6-phosphate dehydrogenase. What best explains it?`,
    options: [r`Glucagon induces synthesis of more of the enzyme`, r`Insulin induces synthesis of more of the enzyme`, r`NADPH allosterically activates the existing enzyme`, r`PKA phosphorylates and activates the existing enzyme`],
    correctAnswer: 1,
    explanation: r`Insulin in the fed state induces glucose 6-phosphate dehydrogenase, raising the amount of enzyme to supply NADPH for fatty acid synthesis. Glucagon is the fasting hormone and does not do this. NADPH is the enzyme's inhibitor, not an activator, and a rise in enzyme amount over days points to induction rather than covalent modification.`,
  },
  [r`How can muscle glycogen phosphorylase b become active during sprinting even before any hormonal signal arrives?`]: {
    question: r`Unphosphorylated glycogen phosphorylase b from muscle and from liver are each tested in a tube with AMP added and no kinase. Which is activated?`,
    options: [r`Neither of the forms, since only phosphorylation activates b`, r`Both of the forms, since AMP activates every phosphorylase b`, r`Only the liver form, which responds to local energy charge`, r`Only the muscle form, which responds to local energy charge`],
    correctAnswer: 3,
    explanation: r`Muscle phosphorylase b is allosterically activated by AMP, so a falling energy charge turns it on without any hormone. The liver isozyme is insensitive to AMP because liver glycogen serves blood glucose, not the cell's own energy needs. So 'both' and 'neither' are each wrong for one of the two isozymes.`,
  },
  [r`The UDP-glucose pyrophosphorylase reaction is nearly isoenergetic. What actually makes UDP-glucose formation irreversible in vivo?`]: {
    question: r`A cell's inorganic pyrophosphatase is inhibited. What happens to the formation of UDP-glucose from glucose 1-phosphate and UTP?`,
    options: [r`It slows, as UTP can no longer be remade from UDP and ATP`, r`It slows, as PPᵢ builds up and the reaction nears equilibrium`, r`It speeds up, as PPᵢ builds up and passes phosphate to ADP`, r`It is unchanged, as the step itself is strongly exergonic`],
    correctAnswer: 1,
    explanation: r`The pyrophosphorylase reaction has a standard free energy change near zero; it is pulled forward only because pyrophosphatase destroys the PPᵢ product. Without that, PPᵢ accumulates and net formation stalls. PPᵢ does not phosphorylate ADP here, UTP regeneration is a separate reaction, and the step is not exergonic on its own.`,
  },
  [r`A patient with exercise-induced cramps shows a flat venous lactate curve during ischemic forearm testing and a second-wind phenomenon. Diagnosis and logic?`]: {
    question: r`A patient with McArdle disease is given a glucagon injection after an overnight fast. How does blood glucose respond?`,
    options: [r`It fails to rise, because liver glucose 6-phosphatase is absent`, r`It rises normally, because liver glycogen phosphorylase is intact`, r`It rises normally, because muscle exports glucose from glycogen`, r`It fails to rise, because liver glycogen phosphorylase is absent`],
    correctAnswer: 1,
    explanation: r`McArdle disease is a deficiency of the muscle isozyme of glycogen phosphorylase only, so the liver still breaks down glycogen and blood glucose responds normally. A failed response from the liver would point to a hepatic storage disease such as glucose 6-phosphatase deficiency. Muscle never exports glucose, with or without the disease.`,
  },
  [r`In the nonoxidative PPP, {{c1::transketolase}} transfers 2-carbon units and requires {{c2::thiamine pyrophosphate}}; transaldolase moves {{c3::3}}-carbon units.`]: {
    question: r`Transketolase acts on two 5-carbon sugar phosphates, xylulose 5-phosphate (donor) and ribose 5-phosphate (acceptor). What are the sizes of the two products?`,
    options: [r`A 2-carbon sugar and an 8-carbon sugar`, r`A 5-carbon sugar and a 5-carbon sugar`, r`A 4-carbon sugar and a 6-carbon sugar`, r`A 3-carbon sugar and a 7-carbon sugar`],
    correctAnswer: 3,
    explanation: r`Transketolase moves a 2-carbon unit, so the donor drops from 5 to 3 carbons and the acceptor grows from 5 to 7 (glyceraldehyde 3-phosphate and sedoheptulose 7-phosphate). A 2 and 8 split would need a 3-carbon transfer, which is what transaldolase does. The 4 and 6 split moves one carbon, and two 5-carbon products would mean no transfer at all.`,
  },
  [r`Beyond fatty acid synthesis, name three other major consumers of NADPH.`]: {
    question: r`A drug depletes NADPH in many tissues. Which process is LEAST directly affected?`,
    options: [r`Superoxide production by NADPH oxidase in neutrophils`, r`Drug hydroxylation by cytochrome P450 in the liver`, r`Pyruvate oxidation by pyruvate dehydrogenase in muscle`, r`Glutathione reduction by its reductase in red cells`],
    correctAnswer: 2,
    explanation: r`Pyruvate dehydrogenase uses NAD⁺ and makes NADH; it does not use NADPH. The respiratory burst of phagocytes, cytochrome P450 monooxygenases and glutathione reductase are all major NADPH consumers, along with fatty acid and cholesterol synthesis, so each of those three would fail directly.`,
  },
  [r`Von Gierke disease (G6Pase deficiency) causes severe {{c1::fasting hypoglycemia}} WITH {{c2::lactic acidosis}}, hepatomegaly, and hyperuricemia.`]: {
    question: r`A child with glucose 6-phosphatase deficiency is given glucagon after a short fast. What happens to blood glucose and blood lactate?`,
    options: [r`Glucose rises and lactate rises further`, r`Glucose rises and lactate falls toward normal`, r`Glucose stays low and lactate rises further`, r`Glucose stays low and lactate stays normal`],
    correctAnswer: 2,
    explanation: r`Glucagon breaks down glycogen to glucose 6-phosphate, but without the phosphatase no free glucose can leave the liver. The trapped glucose 6-phosphate runs down glycolysis to lactate, worsening the lactic acidosis. Any answer with rising glucose ignores the block, and normal lactate describes storage diseases in which gluconeogenesis is intact.`,
  },
  [r`Fructose: {{c1::fructokinase}} makes F1P, {{c2::aldolase B}} cleaves it, and the carbons enter glycolysis below {{c3::PFK-1}}.`]: {
    question: r`In a hepatocyte, PFK-1 is strongly inhibited by ATP and citrate. Which sugar's carbons can still flow readily to pyruvate, and why?`,
    options: [r`Fructose, entering as fructose 6-phosphate at PFK-1`, r`Fructose, entering as trioses below the PFK-1 step`, r`Glucose, entering as a hexose above the PFK-1 step`, r`Galactose, entering as trioses below the PFK-1 step`],
    correctAnswer: 1,
    explanation: r`In liver, fructokinase makes fructose 1-phosphate and aldolase B splits it into dihydroxyacetone phosphate and glyceraldehyde, which join glycolysis below PFK-1 and escape its control. Glucose must pass PFK-1. Hepatic fructose does not enter as fructose 6-phosphate, and galactose is converted to glucose 6-phosphate, above the block.`,
  },
  [r`HFI ({{c1::aldolase B}} deficiency): F1P traps {{c2::phosphate}}, causing hypoglycemia after fructose; {{c3::fructokinase}} deficiency is benign.`]: {
    question: r`An infant newly weaned onto fruit juice vomits and becomes hypoglycemic after feeds. An unrelated adult has fructose in the urine but no symptoms. Which enzyme does the infant lack, and what causes the hypoglycemia?`,
    options: [r`Fructokinase; free fructose builds up and traps phosphate`, r`Aldolase B; fructose is lost in urine before it can be used`, r`Fructokinase; fructose 1-phosphate builds up and traps phosphate`, r`Aldolase B; fructose 1-phosphate builds up and traps phosphate`],
    correctAnswer: 3,
    explanation: r`Hereditary fructose intolerance is aldolase B deficiency: fructose 1-phosphate accumulates and ties up phosphate, which cripples glycogenolysis and gluconeogenesis. Fructokinase deficiency is the benign condition of the adult, because no fructose 1-phosphate is made at all. Losing fructose in urine does not cause hypoglycemia.`,
  },
  [r`Classic galactosemia = {{c1::GALT}} deficiency; {{c2::galactokinase}} deficiency causes mainly cataracts via {{c3::galactitol}}.`]: {
    question: r`Infant A develops jaundice, liver failure and cataracts after milk feeds. Child B, who also cannot use galactose normally, has only cataracts. Which enzyme does child B lack, and why is the disease milder?`,
    options: [r`Galactokinase; no galactitol is formed in the lens`, r`GALT; no galactose 1-phosphate is formed`, r`Galactokinase; no galactose 1-phosphate is formed`, r`GALT; no galactitol is formed in the lens`],
    correctAnswer: 2,
    explanation: r`Galactokinase deficiency stops the pathway before galactose 1-phosphate, the toxic compound that damages the liver in classic galactosemia, so only cataracts appear. GALT deficiency is infant A: galactose 1-phosphate is made and trapped. Both children form galactitol in the lens through aldose reductase, which is why both get cataracts.`,
  },
  [r`Insulin binds a {{c1::receptor tyrosine kinase}} that autophosphorylates and signals through IRS and {{c2::PI3K-Akt}} to move GLUT4 to the surface.`]: {
    question: r`Fat cells are treated with an inhibitor of PI3K and then with insulin. What is observed?`,
    options: [r`The receptor autophosphorylates, and GLUT4 moves to the surface`, r`The receptor autophosphorylates, but GLUT4 stays in vesicles`, r`The receptor cannot autophosphorylate, and GLUT4 stays in vesicles`, r`The receptor cannot autophosphorylate, but GLUT4 moves to the surface`],
    correctAnswer: 1,
    explanation: r`The insulin receptor is a receptor tyrosine kinase that autophosphorylates as soon as insulin binds, which is upstream of PI3K and unaffected by the drug. GLUT4 movement to the membrane depends on the PI3K-Akt branch, so it is blocked. Answers that stop autophosphorylation place PI3K before the receptor, and GLUT4 cannot move without Akt signaling.`,
  },
  [r`The polyol pathway converts glucose to {{c1::sorbitol}} through {{c2::aldose reductase}}, harming tissues that cannot clear it.`]: {
    question: r`In a patient with high blood glucose, lens cells make sorbitol faster than they can remove it. The damage to the lens arises mainly because:`,
    options: [r`sorbitol binds to hexokinase and shuts down glycolysis`, r`sorbitol is oxidized in the cell and uses up all the ATP`, r`sorbitol leaves the cell and draws water out by osmosis`, r`sorbitol stays in the cell and draws water in by osmosis`],
    correctAnswer: 3,
    explanation: r`Aldose reductase turns excess glucose into sorbitol, a polyol that cannot cross the membrane easily; in tissues that clear it slowly it accumulates, raises osmotic pressure, and swells the cell. Sorbitol does not leave freely, which is the whole problem. It is not a major ATP drain and it does not inhibit hexokinase.`,
  },
  [r`Rapidly dividing tumor cells favor {{c1::aerobic glycolysis}}, the Warburg effect, even when oxygen is plentiful.`]: {
    question: r`Tumor cells and normal resting cells are grown with plentiful oxygen. Which pattern is expected in the tumor cells?`,
    options: [r`Low glucose uptake, with most pyruvate oxidized to CO₂`, r`High glucose uptake, with most pyruvate reduced to lactate`, r`Low glucose uptake, with most pyruvate reduced to lactate`, r`High glucose uptake, with most pyruvate oxidized to CO₂`],
    correctAnswer: 1,
    explanation: r`In the Warburg effect, dividing tumor cells run glycolysis at a high rate and make lactate even with oxygen available, using glycolytic intermediates for biosynthesis. This is why they take up so much glucose on a PET scan. Low uptake contradicts that avid consumption, and full oxidation to CO₂ is the pattern of normal resting cells.`,
  },
  [r`Lactase deficiency is confirmed by a {{c1::hydrogen breath}} test because colonic bacteria ferment the undigested {{c2::lactose}}.`]: {
    question: r`An adult drinks 50 g of lactose. Breath hydrogen rises sharply at 90 minutes and blood glucose stays flat. What happened to the lactose?`,
    options: [r`It reached the colon intact and was fermented by bacteria`, r`It was split by lactase and its glucose was absorbed`, r`It was absorbed intact and then oxidized by the liver`, r`It was split by lactase and its galactose formed hydrogen`],
    correctAnswer: 0,
    explanation: r`Human cells do not make hydrogen gas, so a rise in breath hydrogen shows that colonic bacteria fermented undigested lactose, which confirms lactase deficiency. If lactase had split the sugar, blood glucose would have risen and no hydrogen would appear. Lactose is not absorbed intact, and galactose metabolism does not release hydrogen.`,
  },
  [r`Metformin lowers glucose by suppressing hepatic {{c1::gluconeogenesis}} and activating {{c2::AMPK}}; its rare serious toxicity is {{c3::lactic acidosis}}.`]: {
    question: r`A patient taking metformin as the only diabetes drug skips a meal. What is the risk of hypoglycemia, and why?`,
    options: [r`Low: it only blocks glucose absorption from the gut`, r`High: it closes beta-cell K⁺ channels and raises insulin`, r`Low: it cuts liver glucose output without raising insulin`, r`High: it moves GLUT4 to the surface in place of insulin`],
    correctAnswer: 2,
    explanation: r`Metformin activates AMPK and suppresses hepatic gluconeogenesis but does not stimulate insulin secretion, so on its own it does not cause hypoglycemia. Closing beta-cell potassium channels is how sulfonylureas work, and they do carry that risk. Metformin does not replace insulin at GLUT4, and its main action is on the liver, not gut absorption.`,
  },
  [r`Hemoglobin A1c reflects roughly {{c1::3 months}} of glycemia because it forms {{c2::nonenzymatically}} and red cells survive about 120 days.`]: {
    question: r`A patient with poorly controlled diabetes also has a hemolytic anemia that cuts red cell lifespan to about 40 days. How will the hemoglobin A1c result compare with the true glycemic control?`,
    options: [r`Accurate: enzymes hold glycation at a fixed rate`, r`Falsely high: young cells are glycated more quickly`, r`Falsely high: hemolysis releases glycated hemoglobin`, r`Falsely low: cells have less time to pick up glucose`],
    correctAnswer: 3,
    explanation: r`Hemoglobin is glycated nonenzymatically in proportion to how long the red cell is exposed to glucose, so cells that die early carry less A1c and the result reads falsely low. Young cells are not glycated faster. No enzyme controls the reaction, and the test measures the fraction of hemoglobin glycated inside surviving cells.`,
  },
  [r`Normal fasting plasma glucose is {{c1::70-100}} mg/dL, and diabetes is diagnosed at a fasting value of {{c2::126}} mg/dL or above.`]: {
    question: r`A patient's fasting plasma glucose is 7.0 mM on two separate mornings. Glucose has a molar mass of 180 g/mol. What is this value in mg/dL, and how is it classified?`,
    options: [r`126 mg/dL; inside the normal fasting range`, r`39 mg/dL; below the normal fasting range`, r`70 mg/dL; inside the normal fasting range`, r`126 mg/dL; meets the fasting cutoff for diabetes`],
    correctAnswer: 3,
    explanation: r`7.0 mmol/L × 180 mg/mmol = 1260 mg/L = 126 mg/dL, and a fasting value of 126 mg/dL or above is diagnostic of diabetes. Calling 126 normal ignores that the normal fasting range is 70 to 100 mg/dL. The 70 answer multiplies by 10, and 39 divides by 0.18 the wrong way round.`,
  },
  [r`The liver stores roughly {{c1::100}} g of glycogen and muscle roughly {{c2::400}} g, while the brain burns about 120 g of glucose daily.`]: {
    question: r`Using typical adult glycogen stores, about how long could the glycogen that can be released into the blood supply a brain that burns 120 g of glucose a day, if nothing else used it?`,
    options: [r`About 20 hours`, r`About 100 hours`, r`About 80 hours`, r`About 5 hours`],
    correctAnswer: 0,
    explanation: r`Only the liver's roughly 100 g of glycogen can leave as blood glucose, and 100 g ÷ 120 g/day is about 0.8 day, or 20 hours. Eighty hours uses the 400 g muscle store, which cannot be exported because muscle lacks glucose 6-phosphatase. One hundred hours uses both stores together, and 5 hours greatly underestimates the liver store.`,
  },
  [r`Iodoacetate blocks glycolysis by alkylating the active-site {{c1::cysteine}} of {{c2::glyceraldehyde 3-phosphate dehydrogenase}}.`]: {
    question: r`Cells are treated with iodoacetate. Which change in glycolytic intermediates is expected?`,
    options: [r`Phosphoenolpyruvate rises; pyruvate falls`, r`Glyceraldehyde 3-phosphate rises; 1,3-bisphosphoglycerate falls`, r`Glyceraldehyde 3-phosphate falls; 1,3-bisphosphoglycerate rises`, r`2-Phosphoglycerate rises; phosphoenolpyruvate falls`],
    correctAnswer: 1,
    explanation: r`Iodoacetate alkylates the active-site cysteine of glyceraldehyde 3-phosphate dehydrogenase, so its substrate piles up and its product, 1,3-bisphosphoglycerate, is no longer made. The reversed answer swaps substrate and product. A block between 2-phosphoglycerate and phosphoenolpyruvate is fluoride acting on enolase, and a block before pyruvate would be at pyruvate kinase.`,
  },
  [r`Why does heavy drinking on an empty stomach cause hypoglycemia?`]: {
    question: r`A fasting man's liver is metabolizing a large amount of ethanol. Lactate is plentiful in his blood, yet his liver makes little glucose from it. Why?`,
    options: [r`High NAD⁺ keeps pyruvate from being made into glucose`, r`High NADH keeps lactate from being oxidized to pyruvate`, r`Low NADH keeps lactate from being oxidized to pyruvate`, r`Low ATP keeps lactate from being taken up by the liver`],
    correctAnswer: 1,
    explanation: r`Alcohol dehydrogenase and acetaldehyde dehydrogenase flood the cytosol with NADH, which pushes pyruvate toward lactate and oxaloacetate toward malate, so gluconeogenesis has no substrate. Low NADH or high NAD⁺ is the opposite of what ethanol does and would favor lactate oxidation. Ethanol oxidation does not work by blocking lactate uptake.`,
  },
  [r`Why are red blood cells uniquely vulnerable in G6PD deficiency?`]: {
    question: r`A man has an unstable variant of glucose 6-phosphate dehydrogenase that breaks down within weeks of being made. Which of his cells have the least enzyme activity?`,
    options: [r`Old red cells, which cannot make any new enzyme`, r`Reticulocytes, which have not yet made the enzyme`, r`Hepatocytes, which carry the highest oxidant load`, r`Lymphocytes, which lack the pentose phosphate pathway`],
    correctAnswer: 0,
    explanation: r`Mature red cells have no nucleus, so they cannot replace the enzyme as it degrades, and the oldest cells have the least left; with no mitochondria they also have no other source of reducing power. Reticulocytes are the youngest red cells and have the most enzyme. Nucleated cells such as hepatocytes and lymphocytes keep making fresh enzyme.`,
  },
  [r`In the beta cell, glucose metabolism raises ATP, which {{c1::closes}} $K_{ATP}$ channels, depolarizes the membrane, and opens {{c2::$Ca^{2+}$}} channels.`]: {
    question: r`A drug holds the ATP-sensitive K⁺ channels of beta cells open. What happens when these cells are exposed to high glucose?`,
    options: [r`They depolarize, so Ca²⁺ entry and insulin release rise`, r`They stay polarized, so Ca²⁺ entry and insulin release fall`, r`They stay polarized, so Ca²⁺ entry and insulin release rise`, r`They depolarize, so Ca²⁺ entry and insulin release fall`],
    correctAnswer: 1,
    explanation: r`Glucose normally raises ATP, which closes these K⁺ channels, depolarizes the membrane and opens voltage-gated Ca²⁺ channels to trigger insulin release. If the channels are held open, the membrane stays polarized and Ca²⁺ does not enter. Depolarization with more insulin is the normal or sulfonylurea response, and the mixed answers break the link between voltage and Ca²⁺ entry.`,
  },
  [r`G6PD deficiency causes hemolysis because red cells cannot regenerate {{c1::NADPH}} to keep {{c2::glutathione}} reduced.`]: {
    question: r`Red cells from a patient with glucose 6-phosphate dehydrogenase deficiency are exposed to hydrogen peroxide. What happens to reduced glutathione (GSH) and oxidized glutathione (GSSG)?`,
    options: [r`GSH rises and GSSG falls, as NADH cannot be consumed`, r`GSH falls and GSSG rises, as NADPH cannot be regenerated`, r`GSH falls and GSSG rises, as NADH cannot be regenerated`, r`GSH rises and GSSG falls, as NADPH cannot be consumed`],
    correctAnswer: 1,
    explanation: r`Peroxide is removed by oxidizing GSH to GSSG, and glutathione reductase needs NADPH to turn GSSG back into GSH. Without the dehydrogenase the red cell cannot regenerate NADPH, so GSH is used up and GSSG accumulates. NADH is made normally by glycolysis and is not the cofactor for glutathione reductase.`,
  },
  [r`Red cells lack {{c1::mitochondria}}, so they make ATP only by {{c2::glycolysis}} and must export {{c3::lactate}}.`]: {
    question: r`A red blood cell consumes 100 glucose molecules, none passing through any shunt. What does it produce?`,
    options: [r`200 lactate and a net 400 ATP`, r`600 CO₂ and a net 3000 ATP`, r`200 lactate and a net 200 ATP`, r`100 lactate and a net 200 ATP`],
    correctAnswer: 2,
    explanation: r`Red cells have no mitochondria, so each glucose goes through glycolysis to 2 lactate with a net 2 ATP: 200 lactate and 200 ATP. Four hundred ATP counts the gross yield without the 2 invested per glucose. Carbon dioxide and about 30 ATP per glucose need mitochondria, and 100 lactate forgets that each glucose gives two.`,
  },
  [r`In untreated type 1 diabetes, blood glucose is high yet tissues behave as if {{c1::starving}}, because {{c2::insulin}} is absent.`]: {
    question: r`A patient with untreated type 1 diabetes has a blood glucose of 400 mg/dL. What are adipose tissue and the liver doing?`,
    options: [r`Lipolysis is high and hepatic glucose output is low`, r`Lipolysis is low and hepatic glucose output is low`, r`Lipolysis is low and hepatic glucose output is high`, r`Lipolysis is high and hepatic glucose output is high`],
    correctAnswer: 3,
    explanation: r`Without insulin, tissues respond as they would in starvation despite the high blood glucose: adipose releases fatty acids and the liver keeps making glucose and ketone bodies. Low lipolysis and low hepatic output are both insulin effects, which is exactly what is missing. The fatty acids feed the ketogenesis that leads to ketoacidosis.`,
  },
  [r`Intestinal glucose uptake uses {{c1::SGLT1}}, a $Na^+$-coupled {{c2::secondary active}} transporter, while fructose enters passively through {{c3::GLUT5}}.`]: {
    question: r`Intestinal cells are treated with a drug that blocks the Na⁺/K⁺-ATPase on their basolateral side. What happens to uptake of glucose and of fructose from the gut lumen?`,
    options: [r`Glucose uptake falls; fructose uptake is largely unchanged`, r`Fructose uptake falls; glucose uptake is largely unchanged`, r`Glucose uptake falls; fructose uptake falls just as much`, r`Glucose uptake is unchanged; fructose uptake is unchanged`],
    correctAnswer: 0,
    explanation: r`Glucose enters through SGLT1, a secondary active transporter driven by the Na⁺ gradient that the Na⁺/K⁺-ATPase maintains, so it fails when the pump stops. Fructose enters by facilitated diffusion through GLUT5 and needs no Na⁺ gradient. The other answers swap the two transporters or treat both sugars as using the same mechanism.`,
  },
  [r`Why does 2-deoxyglucose trap itself inside cells, and how is that exploited in imaging?`]: {
    question: r`Cells that lack hexokinase but have normal glucose transporters are incubated with 2-deoxyglucose. What happens to the compound?`,
    options: [r`It moves in and out freely and is not trapped`, r`It is carried through glycolysis to pyruvate`, r`It cannot get in, as transporters reject it`, r`It is trapped as 2-deoxyglucose 6-phosphate`],
    correctAnswer: 0,
    explanation: r`2-Deoxyglucose is trapped only because hexokinase phosphorylates it to a charged product that cannot leave or go further. Without hexokinase it stays unphosphorylated and can exit through the same transporters it entered by. It does enter cells on glucose transporters, and it can never continue through glycolysis, with or without hexokinase.`,
  },
  [r`A rising lactate-to-pyruvate ratio in a tissue is a direct readout of which intracellular quantity?`]: {
    question: r`After a Complex I inhibitor is given, the lactate-to-pyruvate ratio in a tissue rises from 10 to 40. What does this show?`,
    options: [r`Cytosolic NADH/NAD⁺ has fallen about fourfold`, r`Cytosolic NADPH/NADP⁺ has risen about fourfold`, r`Cytosolic NADH/NAD⁺ has risen about fourfold`, r`Mitochondrial ATP/ADP has risen about fourfold`],
    correctAnswer: 2,
    explanation: r`Lactate dehydrogenase is near equilibrium, so the lactate-to-pyruvate ratio tracks the cytosolic NADH-to-NAD⁺ ratio; a fourfold rise in one reflects a fourfold rise in the other. A fall is the wrong direction, since blocking Complex I stops NADH from being reoxidized. NADPH is not this enzyme's cofactor, and ATP/ADP falls when Complex I is blocked.`,
  },
}
